 49→void CESReader::DetectFormat() {
 50→  // Check for CES compliance via global attribute
 51→  char version_buf[64] = {0};
 52→  int status = nc_get_att_text(ncid_, NC_GLOBAL, "miem_version", version_buf);
 53→  is_ces_compliant_ = (status == NC_NOERR);
 54→
 55→  // Get time dimension
 56→  int time_dim_id;
 57→  const std::string& time_dim_name =
 58→      is_ces_compliant_ ? "Time" : descriptor_.time_dimension;
 59→  status = nc_inq_dimid(ncid_, time_dim_name.c_str(), &time_dim_id);
 60→  if (status == NC_NOERR) {
 61→    size_t time_len;
 62→    NC_CHECK(nc_inq_dimlen(ncid_, time_dim_id, &time_len));
 63→    n_time_steps_ = static_cast<int>(time_len);
 64→  } else {
 65→    n_time_steps_ = 1;  // No time dimension; treat as single snapshot
 66→  }
 67→
 68→  // Get cell dimension
 69→  int cell_dim_id;
 70→  const std::string& cell_dim_name =
 71→      is_ces_compliant_ ? "nCells" : descriptor_.cell_dimension;
 72→  status = nc_inq_dimid(ncid_, cell_dim_name.c_str(), &cell_dim_id);
 73→  if (status != NC_NOERR) {
 74→    throw IOError("Cannot find cell dimension '" + cell_dim_name +
 75→                  "' in file: " + file_path_);
 76→  }
 77→  size_t cell_len;
 78→  NC_CHECK(nc_inq_dimlen(ncid_, cell_dim_id, &cell_len));
 79→  n_cells_ = static_cast<int>(cell_len);
 80→}
