 82→void CESReader::DiscoverSpecies() {
 83→  available_species_.clear();
 84→
 85→  int n_vars;
 86→  NC_CHECK(nc_inq_nvars(ncid_, &n_vars));
 87→
 88→  const std::string& prefix =
 89→      is_ces_compliant_ ? "emi_" : descriptor_.variable_prefix;
 90→
 91→  for (int varid = 0; varid < n_vars; ++varid) {
 92→    char var_name[NC_MAX_NAME + 1];
 93→    NC_CHECK(nc_inq_varname(ncid_, varid, var_name));
 94→
 95→    std::string name(var_name);
 96→    if (name.substr(0, prefix.size()) == prefix) {
 97→      std::string species = CanonicalName(name);
 98→      available_species_.push_back(species);
 99→    }
100→  }
101→}
