103→std::string CESReader::CanonicalName(const std::string& var_name) const {
104→  // Check descriptor rename map first
105→  auto it = descriptor_.species_rename.find(var_name);
106→  if (it != descriptor_.species_rename.end()) {
107→    // The rename target should be in emi_X format; strip prefix
108→    const std::string& renamed = it->second;
109→    if (renamed.substr(0, 4) == "emi_") {
110→      return renamed.substr(4);
111→    }
112→    return renamed;
113→  }
114→
115→  // Strip the variable prefix to get species name
116→  const std::string& prefix =
117→      is_ces_compliant_ ? "emi_" : descriptor_.variable_prefix;
118→  if (var_name.substr(0, prefix.size()) == prefix) {
119→    return var_name.substr(prefix.size());
120→  }
121→  return var_name;
122→}
