124→std::vector<std::string> CESReader::QuerySpecies() const {
125→  return available_species_;
126→}
127→
128→std::vector<double> CESReader::GetTimeValues() const {
129→  std::vector<double> times(n_time_steps_, 0.0);
130→
131→  int time_varid;
132→  const std::string& time_dim_name =
133→      is_ces_compliant_ ? "Time" : descriptor_.time_dimension;
134→  int status = nc_inq_varid(ncid_, time_dim_name.c_str(), &time_varid);
135→  if (status == NC_NOERR) {
136→    NC_CHECK(nc_get_var_double(ncid_, time_varid, times.data()));
137→  }
138→
139→  return times;
140→}
141→
142→void CESReader::ReadFlux(int time_index,
143→                         const std::vector<std::string>& species_names,
144→                         std::vector<Real>& flux_out,
145→                         int& n_cells_out) const {
146→  if (ncid_ < 0) {
147→    throw IOError("CESReader: file not open");
148→  }
149→
150→  n_cells_out = n_cells_;
151→  int n_species = static_cast<int>(species_names.size());
152→  flux_out.resize(static_cast<size_t>(n_species) * n_cells_, 0.0);
153→
154→  const std::string& prefix =
155→      is_ces_compliant_ ? "emi_" : descriptor_.variable_prefix;
156→
157→  for (int isp = 0; isp < n_species; ++isp) {
158→    // Build variable name from species name
159→    std::string var_name = prefix + species_names[isp];
160→
161→    // Check if descriptor has a reverse rename
162→    // (we need to map canonical name back to file variable name)
163→    if (!is_ces_compliant_) {
164→      for (const auto& [file_var, canonical] : descriptor_.species_rename) {
165→        std::string canon_species =
166→            (canonical.substr(0, 4) == "emi_") ? canonical.substr(4) : canonical;
167→        if (canon_species == species_names[isp]) {
168→          var_name = file_var;
169→          break;
170→        }
171→      }
172→    }
173→
174→    int varid;
175→    int status = nc_inq_varid(ncid_, var_name.c_str(), &varid);
176→    if (status != NC_NOERR) {
177→      continue;  // Species not in file; leave as zero
178→    }
179→
180→    // Determine dimensionality
181→    int ndims;
182→    NC_CHECK(nc_inq_varndims(ncid_, varid, &ndims));
183→
184→    std::vector<Real> raw(n_cells_);
185→
186→    if (ndims == 2) {
187→      // (Time, nCells)
188→      size_t start[2] = {static_cast<size_t>(time_index), 0};
189→      size_t count[2] = {1, static_cast<size_t>(n_cells_)};
190→#ifdef MIEM_USE_DOUBLE
191→      NC_CHECK(nc_get_vara_double(ncid_, varid, start, count, raw.data()));
192→#else
193→      NC_CHECK(nc_get_vara_float(ncid_, varid, start, count, raw.data()));
194→#endif
195→    } else if (ndims == 1) {
196→      // (nCells) — single time step
197→#ifdef MIEM_USE_DOUBLE
198→      NC_CHECK(nc_get_var_double(ncid_, varid, raw.data()));
199→#else
200→      NC_CHECK(nc_get_var_float(ncid_, varid, raw.data()));
201→#endif
202→    }
203→
204→    // Apply unit conversion
205→    Real conv = descriptor_.unit_conversion_factor;
206→    for (int ic = 0; ic < n_cells_; ++ic) {
207→      flux_out[isp * n_cells_ + ic] = raw[ic] * conv;
208→    }
209→  }
210→}
