 14→std::vector<std::string> EmissionsModule::QuerySpecies(
 15→    const std::string& config_path) {
 16→  auto config = MIEMConfig::FromYAML(config_path);
 17→
 18→  std::set<std::string> all_species;
 19→  for (const auto& src_config : config.sources) {
 20→    OfflineEmissionSource source(src_config);
 21→    auto sp = source.QuerySpecies();
 22→    all_species.insert(sp.begin(), sp.end());
 23→  }
 24→
 25→  return {all_species.begin(), all_species.end()};
 26→}
 27→
 28→EmissionsModule::EmissionsModule(const std::string& config_path,
 29→                                 int n_cells, int n_vert_levels)
 30→    : n_cells_(n_cells), n_vert_levels_(n_vert_levels) {
 31→  auto config = MIEMConfig::FromYAML(config_path);
 32→
 33→  // Create sources and collect species
 34→  std::set<std::string> species_set;
 35→  for (const auto& src_config : config.sources) {
 36→    auto source = std::make_unique<OfflineEmissionSource>(src_config);
 37→    auto sp = source->QuerySpecies();
 38→    species_set.insert(sp.begin(), sp.end());
 39→    sources_.push_back(std::move(source));
 40→  }
 41→
 42→  aggregated_species_ = {species_set.begin(), species_set.end()};
 43→}
 44→
 45→void EmissionsModule::ResolveHostIndices(
 46→    const std::vector<std::string>& host_species,
 47→    std::vector<int>& indices) const {
 48→  indices.resize(aggregated_species_.size(), -1);
 49→
 50→  // Build host species lookup
 51→  std::map<std::string, int> host_map;
 52→  for (int i = 0; i < static_cast<int>(host_species.size()); ++i) {
 53→    host_map[host_species[i]] = i;
 54→  }
 55→
 56→  for (int i = 0; i < static_cast<int>(aggregated_species_.size()); ++i) {
 57→    auto it = host_map.find(aggregated_species_[i]);
 58→    if (it != host_map.end()) {
 59→      indices[i] = it->second;
 60→    }
 61→  }
 62→}
 63→
 64→EmisState EmissionsModule::Run(double time_current, double dt,
 65→                               const std::vector<Real>& air_density,
 66→                               const std::vector<Real>& layer_thickness) {
 67→  int n_agg = static_cast<int>(aggregated_species_.size());
 68→  EmisState state(n_agg, n_cells_, n_vert_levels_);
 69→  state.species_names = aggregated_species_;
 70→
 71→  // Build index map for aggregation
 72→  std::map<std::string, int> agg_idx;
 73→  for (int i = 0; i < n_agg; ++i) {
 74→    agg_idx[aggregated_species_[i]] = i;
 75→  }
 76→
 77→  // Collect and aggregate flux from all sources
 78→  for (auto& source : sources_) {
 79→    std::vector<Real> src_flux;
 80→    std::vector<std::string> src_species;
 81→    source->Update(time_current, n_cells_, src_flux, src_species);
 82→
 83→    int n_src_sp = static_cast<int>(src_species.size());
 84→    for (int isp = 0; isp < n_src_sp; ++isp) {
 85→      auto it = agg_idx.find(src_species[isp]);
 86→      if (it == agg_idx.end()) continue;
 87→      int dst_idx = it->second;
 88→
 89→      for (int ic = 0; ic < n_cells_; ++ic) {
 90→        state.surface_flux[dst_idx * n_cells_ + ic] +=
 91→            src_flux[isp * n_cells_ + ic];
 92→      }
 93→    }
 94→  }
 95→
 96→  // Convert surface fluxes to tendencies
 97→  FluxConverter::Convert(state, air_density, layer_thickness);
 98→
 99→  return state;
100→}
101→
102→}  // namespace miem
