 37→
 38→void OfflineEmissionSource::LoadBrackets(double time_current) {
 39→  std::string file_path = ResolveFilePath(time_current);
 40→
 41→  reader_.Open(file_path, descriptor_);
 42→  inventory_species_ = reader_.QuerySpecies();
 43→
 44→  auto times = reader_.GetTimeValues();
 45→  int n_cells = reader_.NumCells();
 46→  int n_times = reader_.NumTimeSteps();
 47→
 48→  if (n_times == 0) {
 49→    throw IOError("No time steps in file: " + file_path);
 50→  }
 51→
 52→  // Find bracketing time indices
 53→  int left_idx = 0;
 54→  int right_idx = std::min(1, n_times - 1);
 55→
 56→  if (n_times > 1) {
 57→    for (int t = 0; t < n_times - 1; ++t) {
 58→      if (times[t] <= time_current && time_current <= times[t + 1]) {
 59→        left_idx = t;
 60→        right_idx = t + 1;
 61→        break;
 62→      }
 63→    }
 64→    // If time is beyond last bracket, use last two
 65→    if (time_current > times[n_times - 1]) {
 66→      left_idx = n_times - 2;
 67→      right_idx = n_times - 1;
 68→    }
 69→  }
 70→
 71→  // Read raw inventory data at bracket times
 72→  std::vector<Real> raw_left, raw_right;
 73→  int n_cells_read;
 74→  reader_.ReadFlux(left_idx, inventory_species_, raw_left, n_cells_read);
 75→  reader_.ReadFlux(right_idx, inventory_species_, raw_right, n_cells_read);
 76→
 77→  // Apply species mapping: inventory → mechanism
 78→  std::vector<Real> mapped_left, mapped_right;
 79→  species_map_.Apply(raw_left, inventory_species_, mapped_left, n_cells);
 80→  species_map_.Apply(raw_right, inventory_species_, mapped_right, n_cells);
 81→
 82→  // Set interpolator brackets
 83→  double time_left = (n_times > 0) ? times[left_idx] : 0.0;
 84→  double time_right = (n_times > 1) ? times[right_idx] : time_left + 1.0;
 85→  interpolator_.SetBracket(time_left, time_right, mapped_left, mapped_right);
 86→
 87→  brackets_loaded_ = true;
 88→}
 89→
 90→void OfflineEmissionSource::Update(double time_current, int n_cells,
 91→                                   std::vector<Real>& flux_out,
 92→                                   std::vector<std::string>& species_names_out) {
 93→  // Load brackets if needed
 94→  if (!brackets_loaded_ || !interpolator_.CoversTime(time_current)) {
 95→    LoadBrackets(time_current);
 96→  }
 97→
 98→  // Interpolate to current time
 99→  std::vector<Real> interpolated;
100→  interpolator_.Interpolate(time_current, interpolated);

