 7→namespace miem {
 8→
 9→MIEMConfig MIEMConfig::FromYAML(const std::string& yaml_path) {
10→  YAML::Node root;
11→  try {
12→    root = YAML::LoadFile(yaml_path);
13→  } catch (const YAML::Exception& e) {
14→    throw ConfigError("Failed to load MIEM config: " + yaml_path +
15→                      " — " + e.what());
16→  }
17→
18→  auto miem_node = root["miem"];
19→  if (!miem_node) {
20→    throw ConfigError("Missing 'miem' key in: " + yaml_path);
21→  }
22→
23→  MIEMConfig config;
24→  config.version = miem_node["version"]
25→      ? miem_node["version"].as<std::string>()
26→      : "1.0";
27→
28→  auto sources_node = miem_node["sources"];
29→  if (!sources_node || !sources_node.IsSequence()) {
30→    throw ConfigError("Missing or invalid 'sources' in: " + yaml_path);
31→  }
32→
33→  for (const auto& src : sources_node) {
34→    SourceConfig sc;
35→    sc.name = src["name"].as<std::string>();
36→    sc.type = src["type"] ? src["type"].as<std::string>() : "offline";
37→    sc.file_pattern = src["file_pattern"].as<std::string>();
38→    sc.species_map_path = src["species_map"].as<std::string>();
39→
40→    if (src["temporal_interpolation"]) {
41→      sc.temporal_interpolation =
42→          ParseInterpolationMode(src["temporal_interpolation"].as<std::string>());
43→    }
44→
45→    if (src["vertical_injection"]) {
46→      sc.vertical_injection = src["vertical_injection"].as<std::string>();
47→    }
48→
49→    if (src["descriptor"]) {
50→      sc.descriptor_path = src["descriptor"].as<std::string>();
51→    }
52→
53→    config.sources.push_back(std::move(sc));
54→  }
55→
56→  return config;
57→}
58→
59→}  // namespace miem
