38→                                       std::vector<Real>& output) const {
39→  const size_t n = data_left_.size();
40→  output.resize(n);
41→
42→  switch (mode_) {
43→    case InterpolationMode::kNone:
44→      // Use left bracket data (constant)
45→      output = data_left_;
46→      break;
47→
48→    case InterpolationMode::kNearest: {
49→      double mid = 0.5 * (time_left_ + time_right_);
50→      const auto& src = (time_current <= mid) ? data_left_ : data_right_;
51→      output = src;
52→      break;
53→    }
54→
55→    case InterpolationMode::kLinear: {
56→      double dt = time_right_ - time_left_;
57→      if (dt <= 0.0) {
58→        output = data_left_;
59→        return;
60→      }
61→      double alpha = (time_current - time_left_) / dt;
62→      // Clamp to [0, 1]
63→      alpha = std::max(0.0, std::min(1.0, alpha));
64→
65→      for (size_t i = 0; i < n; ++i) {
66→        output[i] = data_left_[i] * (1.0 - alpha) + data_right_[i] * alpha;
67→      }
68→      break;
