  status = nc_inq_attlen(ncid_, time_varid, "units", &units_len);
  if (status == NC_NOERR && units_len > 0 && units_len < 1024) {
    std::vector<char> units_buf(units_len + 1, '\0');
    nc_get_att_text(ncid_, time_varid, "units", units_buf.data());
