#define NC_CHECK(call)                                                  \
  do {                                                                  \
    int nc_status_ = (call);                                            \
    if (nc_status_ != NC_NOERR) {                                      \
      throw IOError(std::string("NetCDF error: ") + nc_strerror(nc_status_)); \
