137→std::string CESReader::CanonicalName(const std::string& var_name) const {
138→  // Check descriptor rename map first
139→  auto it = descriptor_.species_rename.find(var_name);
140→  if (it != descriptor_.species_rename.end()) {
141→    // The rename target should be in emi_X format; strip prefix
142→    const std::string& renamed = it->second;
143→    if (renamed.substr(0, 4) == "emi_") {
144→      return renamed.substr(4);
145→    }
146→    return renamed;
147→  }
148→
149→  // Strip the variable prefix to get species name
150→  const std::string& prefix =
151→      is_ces_compliant_ ? "emi_" : descriptor_.variable_prefix;
152→  if (var_name.substr(0, prefix.size()) == prefix) {
153→    return var_name.substr(prefix.size());
154→  }
155→  return var_name;
156→}
