164→// Parse CF time units string like "days since 2000-01-01" or
165→// "seconds since 1970-01-01 00:00:00" into a multiplier (to seconds)
166→// and a reference epoch (in seconds since Unix epoch).
167→bool ParseCFTimeUnits(const std::string& units_str,
168→                      double& multiplier, double& ref_epoch) {
169→  // Pattern: "<unit> since <date> [<time>]"
170→  std::regex cf_pattern(
171→      R"((\w+)\s+since\s+(\d{4})-(\d{1,2})-(\d{1,2})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?)");
172→  std::smatch match;
173→  if (!std::regex_search(units_str, match, cf_pattern)) {
174→    return false;
175→  }
176→
177→  std::string unit = match[1].str();
178→  int year = std::stoi(match[2].str());
179→  int month = std::stoi(match[3].str());
180→  int day = std::stoi(match[4].str());
181→  int hour = match[5].matched ? std::stoi(match[5].str()) : 0;
182→  int minute = match[6].matched ? std::stoi(match[6].str()) : 0;
183→  int second = match[7].matched ? std::stoi(match[7].str()) : 0;
184→
185→  // Unit to seconds multiplier
186→  if (unit == "seconds" || unit == "second" || unit == "s") {
187→    multiplier = 1.0;
188→  } else if (unit == "minutes" || unit == "minute") {
189→    multiplier = 60.0;
190→  } else if (unit == "hours" || unit == "hour" || unit == "h") {
191→    multiplier = 3600.0;
192→  } else if (unit == "days" || unit == "day" || unit == "d") {
193→    multiplier = 86400.0;
194→  } else {
195→    return false;
196→  }
197→
198→  // Convert reference date to seconds since Unix epoch
199→  std::tm ref_tm{};
200→  ref_tm.tm_year = year - 1900;
201→  ref_tm.tm_mon = month - 1;
202→  ref_tm.tm_mday = day;
203→  ref_tm.tm_hour = hour;
204→  ref_tm.tm_min = minute;
205→  ref_tm.tm_sec = second;
206→  ref_epoch = static_cast<double>(timegm(&ref_tm));
207→
208→  return true;
209→}
210→
211→}  // anonymous namespace
