  std::vector<int> flux_varids(species.size());
  int dims2d[2] = {time_dim, cell_dim};
  for (size_t i = 0; i < species.size(); ++i) {
    std::string var_name = "emi_" + species[i];
    nc_def_var(ncid, var_name.c_str(), NC_DOUBLE, 2, dims2d, &flux_varids[i]);
  }

