    // SO2 flux: 3e-6 at t0, 4e-6 at t1
    nox_flux_.resize(n_times_ * n_cells_);
    so2_flux_.resize(n_times_ * n_cells_);
    for (int ic = 0; ic < n_cells_; ++ic) {
