    EXPECT_NEAR(state.surface_flux[so2_idx * n_cells_ + ic],
                3.5e-6, 1e-12);
  }
}

TEST_F(EmissionsIntegrationTest, ResolveHostIndices) {
  EmissionsModule module(config_path_, n_cells_, n_vert_levels_);

