 8→
 9→InterpolationMode ParseInterpolationMode(const std::string& mode_str) {
10→  if (mode_str == "linear") return InterpolationMode::kLinear;
11→  if (mode_str == "nearest") return InterpolationMode::kNearest;
12→  if (mode_str == "none") return InterpolationMode::kNone;
13→  throw ConfigError("Unknown interpolation mode: '" + mode_str +
14→                    "'. Valid options: linear, nearest, none");
15→}
16→
17→TemporalInterpolator::TemporalInterpolator(InterpolationMode mode)
18→    : mode_(mode) {}
19→
20→void TemporalInterpolator::SetBracket(double time_left, double time_right,
21→                                      const std::vector<Real>& data_left,
22→                                      const std::vector<Real>& data_right) {
23→  if (data_left.size() != data_right.size()) {
24→    throw ValidationError(
25→        "TemporalInterpolator: bracket data arrays must have same size");
26→  }
27→  time_left_ = time_left;
28→  time_right_ = time_right;
29→  data_left_ = data_left;
30→  data_right_ = data_right;
31→}
32→
33→bool TemporalInterpolator::CoversTime(double time) const {
34→  return time >= time_left_ && time <= time_right_;
35→}
36→
37→void TemporalInterpolator::Interpolate(double time_current,
38→                                       std::vector<Real>& output) const {
39→  const size_t n = data_left_.size();
40→  output.resize(n);
41→
42→  switch (mode_) {
43→    case InterpolationMode::kNone:
44→      // Use left bracket data (constant)
45→      output = data_left_;
46→      break;
47→
48→    case InterpolationMode::kNearest: {
49→      double mid = 0.5 * (time_left_ + time_right_);
50→      const auto& src = (time_current <= mid) ? data_left_ : data_right_;
51→      output = src;
52→      break;
53→    }
54→
55→    case InterpolationMode::kLinear: {
56→      double dt = time_right_ - time_left_;
57→      if (dt <= 0.0) {
58→        output = data_left_;
59→        return;
60→      }
61→      double alpha = (time_current - time_left_) / dt;
62→      // Clamp to [0, 1]
63→      alpha = std::max(0.0, std::min(1.0, alpha));
64→
65→      for (size_t i = 0; i < n; ++i) {
66→        output[i] = data_left_[i] * (1.0 - alpha) + data_right_[i] * alpha;
67→      }
68→      break;
69→    }
70→  }
71→}
