 44→// Create a minimal CES-compliant NetCDF file with known emission data.
 45→//
 46→// Layout:
 47→//   dimensions: Time=2, nCells=4
 48→//   variables:
 49→//     Time(Time) — seconds since epoch, two monthly snapshots
 50→//     emi_NOx(Time, nCells) — flux values
 51→//     emi_SO2(Time, nCells) — flux values
 52→//   global attributes:
 53→//     miem_version = "1.0"
 54→void CreateTestNetCDF(const std::string& path,
 55→                      int n_times, int n_cells,
 56→                      const std::vector<double>& time_values,
 57→                      const std::vector<std::string>& species,
 58→                      const std::vector<std::vector<double>>& flux_data) {
 59→  int ncid;
 60→  int status = nc_create(path.c_str(), NC_CLOBBER | NC_NETCDF4, &ncid);
 61→  if (status != NC_NOERR)
 62→    throw std::runtime_error("nc_create failed: " + std::string(nc_strerror(status)));
 63→
 64→  // Global attribute for CES compliance
 65→  nc_put_att_text(ncid, NC_GLOBAL, "miem_version", 3, "1.0");
 66→
 67→  // Dimensions
 68→  int time_dim, cell_dim;
 69→  nc_def_dim(ncid, "Time", static_cast<size_t>(n_times), &time_dim);
 70→  nc_def_dim(ncid, "nCells", static_cast<size_t>(n_cells), &cell_dim);
 71→
 72→  // Time variable
 73→  int time_varid;
 74→  nc_def_var(ncid, "Time", NC_DOUBLE, 1, &time_dim, &time_varid);
 75→  const char* time_units = "seconds since 1970-01-01";
 76→  nc_put_att_text(ncid, time_varid, "units",
 77→                  std::strlen(time_units), time_units);
 78→
 79→  // Species flux variables: (Time, nCells)
 80→  std::vector<int> flux_varids(species.size());
 81→  int dims2d[2] = {time_dim, cell_dim};
 82→  for (size_t i = 0; i < species.size(); ++i) {
 83→    std::string var_name = "emi_" + species[i];
 84→    nc_def_var(ncid, var_name.c_str(), NC_DOUBLE, 2, dims2d, &flux_varids[i]);
 85→  }
 86→
 87→  nc_enddef(ncid);
 88→
 89→  // Write time values
 90→  nc_put_var_double(ncid, time_varid, time_values.data());
 91→
 92→  // Write flux data for each species
 93→  for (size_t i = 0; i < species.size(); ++i) {
 94→    nc_put_var_double(ncid, flux_varids[i], flux_data[i].data());
 95→  }
 96→
 97→  nc_close(ncid);
 98→}
