198→                               static_cast<int>(air_density.size()));
199→
200→  EXPECT_EQ(state.n_species, 3);
201→  EXPECT_EQ(state.n_cells, n_cells_);
202→  EXPECT_EQ(state.n_vert_levels, n_vert_levels_);
203→
204→  // Find species indices (sorted: NO, NO2, SO2)
205→  int no_idx = -1, no2_idx = -1, so2_idx = -1;
206→  for (int i = 0; i < static_cast<int>(state.species_names.size()); ++i) {
207→    if (state.species_names[i] == "NO") no_idx = i;
208→    if (state.species_names[i] == "NO2") no2_idx = i;
209→    if (state.species_names[i] == "SO2") so2_idx = i;
210→  }
211→  ASSERT_GE(no_idx, 0);
212→  ASSERT_GE(no2_idx, 0);
213→  ASSERT_GE(so2_idx, 0);
214→
215→  // At t=0: NOx=1e-6, so NO=0.9e-6, NO2=0.1e-6, SO2=3e-6
216→  // Tendency = flux / (rho * dz)
217→  Real no_expected = 0.9e-6 / (rho_val * dz_val);
218→  Real no2_expected = 0.1e-6 / (rho_val * dz_val);
219→  Real so2_expected = 3e-6 / (rho_val * dz_val);
220→
221→  // Check surface flux
222→  for (int ic = 0; ic < n_cells_; ++ic) {
223→    EXPECT_NEAR(state.surface_flux[no_idx * n_cells_ + ic],
224→                0.9e-6, 1e-12);
225→    EXPECT_NEAR(state.surface_flux[no2_idx * n_cells_ + ic],
226→                0.1e-6, 1e-12);
227→    EXPECT_NEAR(state.surface_flux[so2_idx * n_cells_ + ic],
228→                3e-6, 1e-12);
229→  }
230→
231→  // Check tendency at surface layer (layer 0, default injection)
232→  for (int ic = 0; ic < n_cells_; ++ic) {
233→    size_t no_tend = no_idx * n_vert_levels_ * n_cells_ + 0 * n_cells_ + ic;
234→    size_t no2_tend = no2_idx * n_vert_levels_ * n_cells_ + 0 * n_cells_ + ic;
235→    size_t so2_tend = so2_idx * n_vert_levels_ * n_cells_ + 0 * n_cells_ + ic;
236→
237→    EXPECT_NEAR(state.tendency[no_tend], no_expected, 1e-18);
238→    EXPECT_NEAR(state.tendency[no2_tend], no2_expected, 1e-18);
239→    EXPECT_NEAR(state.tendency[so2_tend], so2_expected, 1e-18);
240→
241→    // Layer 1 should be zero (surface injection only)
242→    size_t no_l1 = no_idx * n_vert_levels_ * n_cells_ + 1 * n_cells_ + ic;
243→    EXPECT_DOUBLE_EQ(state.tendency[no_l1], 0.0);
244→  }
245→}
