 8→std::unique_ptr<EmissionSource> SourceFactory::Create(
 9→    const SourceConfig& config) {
10→  // All v1 source types (anthropogenic, fire, biogenic) use offline files.
11→  // Future source types (dust, sea_salt, online_biogenic) would get
12→  // additional branches here.
13→  if (config.type == "anthropogenic" || config.type == "fire" ||
14→      config.type == "biogenic") {
15→    return std::make_unique<OfflineEmissionSource>(config);
16→  }
17→
18→  throw ConfigError("Unknown emission source type: '" + config.type +
19→                    "'. Supported types: anthropogenic, fire, biogenic");
20→}
