 29→TEST(FluxConverter, ConvertEmisState) {
 30→  const int n_species = 2;
 31→  const int n_cells = 3;
 32→  const int n_vert_levels = 2;
 33→
 34→  EmisState state(n_species, n_cells, n_vert_levels);
 35→
 36→  // Set surface fluxes
 37→  for (int isp = 0; isp < n_species; ++isp) {
 38→    for (int ic = 0; ic < n_cells; ++ic) {
 39→      state.surface_flux[isp * n_cells + ic] = 1e-6 * (isp + 1);
 40→    }
 41→  }
 42→
 43→  // All species inject at surface (layer 0, default)
 44→  state.injection_layer = {0, 0};
 45→
 46→  // Set atmospheric state
 47→  std::vector<Real> air_density(n_vert_levels * n_cells);
 48→  std::vector<Real> layer_thickness(n_vert_levels * n_cells);
 49→  for (int k = 0; k < n_vert_levels; ++k) {
 50→    for (int ic = 0; ic < n_cells; ++ic) {
 51→      air_density[k * n_cells + ic] = 1.225 - k * 0.1;
 52→      layer_thickness[k * n_cells + ic] = 100.0 + k * 50.0;
 53→    }
 54→  }
 55→
 56→  FluxConverter::Convert(state, air_density.data(), layer_thickness.data(),
 57→                         static_cast<int>(air_density.size()));
 58→
 59→  // Check tendency at surface layer (layer 0) for species 0
 60→  for (int ic = 0; ic < n_cells; ++ic) {
 61→    Real flux = 1e-6;
 62→    Real rho = air_density[0 * n_cells + ic];
 63→    Real dz = layer_thickness[0 * n_cells + ic];
 64→    Real expected = flux / (rho * dz);
 65→
 66→    size_t tend_idx = 0 * n_vert_levels * n_cells + 0 * n_cells + ic;
 67→    EXPECT_NEAR(state.tendency[tend_idx], expected, 1e-15);
 68→  }
 69→
 70→  // Non-injection layers should be zero
 71→  for (int ic = 0; ic < n_cells; ++ic) {
 72→    size_t tend_idx = 0 * n_vert_levels * n_cells + 1 * n_cells + ic;
 73→    EXPECT_DOUBLE_EQ(state.tendency[tend_idx], 0.0);
 74→  }
 75→}
