213→std::vector<double> CESReader::GetTimeValues() const {
214→  std::vector<double> times(n_time_steps_, 0.0);
215→
216→  int time_varid;
217→  const std::string& time_dim_name =
218→      is_ces_compliant_ ? "Time" : descriptor_.time_dimension;
219→  int status = nc_inq_varid(ncid_, time_dim_name.c_str(), &time_varid);
220→  if (status != NC_NOERR) {
221→    return times;
222→  }
223→
224→  NC_CHECK(nc_get_var_double(ncid_, time_varid, times.data()));
225→
226→  // Read CF units attribute and convert to seconds since Unix epoch
227→  size_t units_len = 0;
228→  status = nc_inq_attlen(ncid_, time_varid, "units", &units_len);
229→  if (status == NC_NOERR && units_len > 0 && units_len < 1024) {
230→    std::vector<char> units_buf(units_len + 1, '\0');
231→    nc_get_att_text(ncid_, time_varid, "units", units_buf.data());
232→    std::string units_str(units_buf.data(), units_len);
233→
234→    double multiplier = 1.0;
235→    double ref_epoch = 0.0;
236→    if (ParseCFTimeUnits(units_str, multiplier, ref_epoch)) {
237→      for (auto& t : times) {
238→        t = t * multiplier + ref_epoch;
239→      }
240→    }
241→  }
242→
243→  return times;
244→}
245→
246→void CESReader::ReadFlux(int time_index,
247→                         const std::vector<std::string>& species_names,
248→                         std::vector<Real>& flux_out,
249→                         int& n_cells_out) const {
250→  if (ncid_ < 0) {
251→    throw IOError("CESReader: file not open");
252→  }
253→
254→  n_cells_out = n_cells_;
255→  int n_species = static_cast<int>(species_names.size());
256→  flux_out.resize(static_cast<size_t>(n_species) * n_cells_, 0.0);
257→
258→  const std::string& prefix =
259→      is_ces_compliant_ ? "emi_" : descriptor_.variable_prefix;
260→
261→  for (int isp = 0; isp < n_species; ++isp) {
262→    // Build variable name from species name
263→    std::string var_name = prefix + species_names[isp];
264→
265→    // Check if descriptor has a reverse rename
266→    // (we need to map canonical name back to file variable name)
267→    if (!is_ces_compliant_) {
268→      for (const auto& [file_var, canonical] : descriptor_.species_rename) {
269→        std::string canon_species =
270→            (canonical.substr(0, 4) == "emi_") ? canonical.substr(4) : canonical;
271→        if (canon_species == species_names[isp]) {
272→          var_name = file_var;
273→          break;
274→        }
275→      }
276→    }
277→
278→    int varid;
279→    int status = nc_inq_varid(ncid_, var_name.c_str(), &varid);
280→    if (status != NC_NOERR) {
281→      continue;  // Species not in file; leave as zero
282→    }
283→
284→    // Determine dimensionality
285→    int ndims;
286→    NC_CHECK(nc_inq_varndims(ncid_, varid, &ndims));
287→
288→    std::vector<Real> raw(n_cells_);
289→
290→    if (ndims == 2) {
291→      // (Time, nCells)
292→      size_t start[2] = {static_cast<size_t>(time_index), 0};
293→      size_t count[2] = {1, static_cast<size_t>(n_cells_)};
294→#ifdef MIEM_USE_DOUBLE
295→      NC_CHECK(nc_get_vara_double(ncid_, varid, start, count, raw.data()));
296→#else
297→      NC_CHECK(nc_get_vara_float(ncid_, varid, start, count, raw.data()));
298→#endif
299→    } else if (ndims == 1) {
300→      // (nCells) — single time step
301→#ifdef MIEM_USE_DOUBLE
302→      NC_CHECK(nc_get_var_double(ncid_, varid, raw.data()));
303→#else
304→      NC_CHECK(nc_get_var_float(ncid_, varid, raw.data()));
305→#endif
306→    }
307→
308→    // Check for fill value / missing value and mask to zero
309→    Real fill_value;
310→    bool has_fill = false;
311→#ifdef MIEM_USE_DOUBLE
312→    double fv;
313→    if (nc_get_att_double(ncid_, varid, "_FillValue", &fv) == NC_NOERR) {
314→      fill_value = fv;
315→      has_fill = true;
316→    }
317→#else
318→    float fv;
319→    if (nc_get_att_float(ncid_, varid, "_FillValue", &fv) == NC_NOERR) {
320→      fill_value = fv;
321→      has_fill = true;
322→    }
323→#endif
324→
325→    // Apply unit conversion and fill value masking
326→    Real conv = descriptor_.unit_conversion_factor;
327→    for (int ic = 0; ic < n_cells_; ++ic) {
328→      Real val = raw[ic];
329→      if (has_fill && val == fill_value) {
330→        val = 0.0;
331→      }
332→      flux_out[isp * n_cells_ + ic] = val * conv;
333→    }
334→  }
335→}
