 69→                               const Real* layer_thickness,
 70→                               int n_atm_elements) {
 71→  int n_agg = static_cast<int>(aggregated_species_.size());
 72→  EmisState state(n_agg, n_cells_, n_vert_levels_);
 73→  state.species_names = aggregated_species_;
 74→
 75→  // Build index map for aggregation
 76→  std::map<std::string, int> agg_idx;
 77→  for (int i = 0; i < n_agg; ++i) {
 78→    agg_idx[aggregated_species_[i]] = i;
 79→  }
 80→
 81→  // Collect and aggregate flux from all sources
 82→  for (auto& source : sources_) {
 83→    std::vector<Real> src_flux;
