116→void CESReader::DiscoverSpecies() {
117→  available_species_.clear();
118→
119→  int n_vars;
120→  NC_CHECK(nc_inq_nvars(ncid_, &n_vars));
121→
122→  const std::string& prefix =
123→      is_ces_compliant_ ? "emi_" : descriptor_.variable_prefix;
124→
125→  for (int varid = 0; varid < n_vars; ++varid) {
126→    char var_name[NC_MAX_NAME + 1];
127→    NC_CHECK(nc_inq_varname(ncid_, varid, var_name));
128→
129→    std::string name(var_name);
130→    if (name.substr(0, prefix.size()) == prefix) {
131→      std::string species = CanonicalName(name);
132→      available_species_.push_back(species);
133→    }
134→  }
135→}
