 31→EmissionsModule::EmissionsModule(const std::string& config_path,
 32→                                 int n_cells, int n_vert_levels)
 33→    : n_cells_(n_cells), n_vert_levels_(n_vert_levels) {
 34→  auto config = MIEMConfig::FromYAML(config_path);
 35→
 36→  // Create sources via factory and collect species
 37→  std::set<std::string> species_set;
 38→  for (const auto& src_config : config.sources) {
 39→    auto source = SourceFactory::Create(src_config);
 40→    auto sp = source->QuerySpecies();
 41→    species_set.insert(sp.begin(), sp.end());
 42→    sources_.push_back(std::move(source));
 43→  }
 44→
 45→  aggregated_species_ = {species_set.begin(), species_set.end()};
 46→}
 47→
 48→void EmissionsModule::ResolveHostIndices(
 49→    const std::vector<std::string>& host_species,
 50→    std::vector<int>& indices) const {
 51→  indices.resize(aggregated_species_.size(), -1);
 52→
 53→  // Build host species lookup
 54→  std::map<std::string, int> host_map;
 55→  for (int i = 0; i < static_cast<int>(host_species.size()); ++i) {
 56→    host_map[host_species[i]] = i;
 57→  }
 58→
 59→  for (int i = 0; i < static_cast<int>(aggregated_species_.size()); ++i) {
 60→    auto it = host_map.find(aggregated_species_[i]);
 61→    if (it != host_map.end()) {
 62→      indices[i] = it->second;
 63→    }
 64→  }
 65→}
 66→
 67→EmisState EmissionsModule::Run(double time_current,
 68→                               const Real* air_density,
 69→                               const Real* layer_thickness,
 70→                               int n_atm_elements) {
 71→  int n_agg = static_cast<int>(aggregated_species_.size());
 72→  EmisState state(n_agg, n_cells_, n_vert_levels_);
 73→  state.species_names = aggregated_species_;
 74→
 75→  // Build index map for aggregation
 76→  std::map<std::string, int> agg_idx;
 77→  for (int i = 0; i < n_agg; ++i) {
 78→    agg_idx[aggregated_species_[i]] = i;
 79→  }
 80→
 81→  // Collect and aggregate flux from all sources
 82→  for (auto& source : sources_) {
 83→    std::vector<Real> src_flux;
 84→    std::vector<std::string> src_species;
 85→    source->Update(time_current, n_cells_, src_flux, src_species);
 86→
 87→    int n_src_sp = static_cast<int>(src_species.size());
 88→    for (int isp = 0; isp < n_src_sp; ++isp) {
 89→      auto it = agg_idx.find(src_species[isp]);
 90→      if (it == agg_idx.end()) continue;
 91→      int dst_idx = it->second;
 92→
 93→      for (int ic = 0; ic < n_cells_; ++ic) {
 94→        state.surface_flux[dst_idx * n_cells_ + ic] +=
 95→            src_flux[isp * n_cells_ + ic];
 96→      }
 97→    }
 98→  }
 99→
100→  // Convert surface fluxes to tendencies
101→  FluxConverter::Convert(state, air_density, layer_thickness, n_atm_elements);
102→
103→  return state;
104→}
