    ToError(MUSICA_ERROR_CATEGORY, 1, "Failed to run TUV-x", error);
    return;
  }
  if (error_code != 0)
  {
    ToError(MUSICA_ERROR_CATEGORY, 1, "Failed to run TUV-x", error);
    return;
  }
